217	    public void savePet(Pet pet) throws DataAccessException {
218	        pet.setType(findPetTypeById(pet.getType().getId()));
219	        petRepository.save(pet);
220	    }
221	
222	    @Override
223	    @Transactional
224	    public void saveVisit(Visit visit) throws DataAccessException {
225	        visitRepository.save(visit);
226	
227	    }
228	
229	    @Override
230	    @Transactional(readOnly = true)
231	    public Collection<Vet> findVets() throws DataAccessException {
232	        return vetRepository.findAll();
233	    }
234	
235	    @Override
236	    @Transactional
237	    public void saveOwner(Owner owner) throws DataAccessException {
238	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
239	        if (owner.isNew()) {
240	            if (hasIdenticalOwner(owner)) {
241	                throw new DuplicateOwnerException();
242	            }
243	            if (hasOwnerWithSameEmail(owner)) {
244	                throw new DuplicateOwnerException("An owner with the same email address already exists");
245	            }
246	            if (hasReachedDailyRegistrationLimit()) {
247	                throw new DailyOwnerRegistrationLimitExceededException();
248	            }
249	            if (hasReachedCityLimit(owner)) {
250	                throw new CityOwnerLimitExceededException();
251	            }
252	            if (owner.getRegistrationDate() == null) {
253	                owner.setRegistrationDate(LocalDate.now());
254	            }
255	            owner.setCity(resolveCity(owner));
256	            owner.setMembershipNumber(ownerRepository.findAll().size() + 1);
257	            owner.setCustomerCode(generateCustomerCode(owner));
258	        }
259	        ownerRepository.save(owner);
260	
261	    }
262	
263	    /**
264	     * Generates a customer code for a newly registered owner, formatted as
265	     * {@code <UPPERCASE_CITY>-<NNNN>} where {@code NNNN} is one more than the number
266	     * of owners already in that city, zero-padded to four digits (e.g. {@code LONDON-0007}).
267	     */
268	    private String generateCustomerCode(Owner owner) {
269	        String city = owner.getCity();
270	        long existingInCity = ownerRepository.findAll().stream()
271	            .filter(existing -> Objects.equals(normalize(existing.getCity()), normalize(city)))
272	            .count();
273	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
274	    }
275	
276	    /**
277	     * Resolves the city to store for a newly registered owner. If another owner already
278	     * lives in the same city (ignoring letter case and surrounding/repeated whitespace),
279	     * that owner's exact spelling of the city name is reused so a city is stored
280	     * consistently. Otherwise the supplied city is title-cased, i.e. each word is
281	     * capitalized and the remaining letters lower-cased (e.g. {@code "new york"} becomes
282	     * {@code "New York"}). Returns {@code null} for a {@code null} input.
283	     */
284	    private String resolveCity(Owner owner) {
285	        String city = owner.getCity();
286	        if (city == null) {
287	            return null;
288	        }
289	        String normalized = normalize(city);
290	        return ownerRepository.findAll().stream()
291	            .map(Owner::getCity)
292	            .filter(existing -> Objects.equals(normalize(existing), normalized))
293	            .findFirst()
294	            .orElseGet(() -> toTitleCase(city));
295	    }
296	
297	    /**
298	     * Title-cases a value by trimming and collapsing whitespace, then capitalizing the
299	     * first letter of each whitespace-separated word and lower-casing the rest
300	     * (e.g. {@code "  new   YORK "} becomes {@code "New York"}).
301	     */
302	    private static String toTitleCase(String value) {
303	        String collapsed = value.trim().replaceAll("\\s+", " ");
304	        if (collapsed.isEmpty()) {
305	            return collapsed;
306	        }
307	        StringBuilder result = new StringBuilder(collapsed.length());
308	        for (String word : collapsed.split(" ")) {
309	            if (result.length() > 0) {
310	                result.append(' ');
311	            }
312	            result.append(Character.toUpperCase(word.charAt(0)))
313	                .append(word.substring(1).toLowerCase(Locale.ROOT));
314	        }
315	        return result.toString();
316	    }
317	
318	    /**
319	     * The maximum number of owners that may be registered on a single day (by registration date).
320	     */
321	    private static final long MAX_OWNERS_PER_DAY = 20;
322	
323	    /**
324	     * Returns {@code true} if the number of owners already registered today (by registration date)
325	     * has reached {@link #MAX_OWNERS_PER_DAY}, so that no further owner may be created today.
326	     */
327	    private boolean hasReachedDailyRegistrationLimit() {
328	        LocalDate today = LocalDate.now();
329	        long registeredToday = ownerRepository.findAll().stream()
330	            .filter(existing -> today.equals(existing.getRegistrationDate()))
331	            .count();
332	        return registeredToday >= MAX_OWNERS_PER_DAY;
333	    }
334	
335	    /**
336	     * The maximum number of owners that may live in a single city.
337	     */
338	    private static final long MAX_OWNERS_PER_CITY = 8;
339	
340	    /**
341	     * Returns {@code true} if the owner's city (compared ignoring letter case and surrounding/repeated
342	     * whitespace) already contains {@link #MAX_OWNERS_PER_CITY} owners, so that no further owner may be
343	     * registered in that city.
344	     */
345	    private boolean hasReachedCityLimit(Owner owner) {
346	        String city = normalize(owner.getCity());
347	        if (city == null) {
348	            return false;
349	        }
350	        long ownersInCity = ownerRepository.findAll().stream()
351	            .filter(existing -> Objects.equals(normalize(existing.getCity()), city))
352	            .count();
353	        return ownersInCity >= MAX_OWNERS_PER_CITY;
354	    }
355	
356	    private boolean hasIdenticalOwner(Owner owner) {
357	        return ownerRepository.findAll().stream()
358	            .anyMatch(existing -> isSameOwner(existing, owner));
359	    }
360	
361	    private boolean isSameOwner(Owner existing, Owner owner) {
362	        return Objects.equals(normalizeTelephone(existing.getTelephone()), normalizeTelephone(owner.getTelephone()));
363	    }
364	
365	    /**
366	     * Normalizes a telephone number for storage and duplicate detection by stripping
367	     * everything except digits (e.g. spaces, dashes and parentheses), so that
368	     * {@code "(613) 555-0100"} and {@code "6135550100"} are treated as the same number.
369	     * Returns {@code null} for a {@code null} input.
370	     */
371	    private static String normalizeTelephone(String telephone) {
372	        if (telephone == null) {
373	            return null;
374	        }
375	        return telephone.replaceAll("[^0-9]", "");
376	    }
377	
378	    private boolean hasOwnerWithSameEmail(Owner owner) {
379	        String email = normalize(owner.getEmail());
380	        if (email == null || email.isEmpty()) {
381	            return false;
382	        }
383	        return ownerRepository.findAll().stream()
384	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
385	    }
386	
387	    /**
388	     * Normalizes a value for duplicate detection so that values differing only in
389	     * letter case or in surrounding/repeated whitespace compare as equal. Surrounding
390	     * whitespace is trimmed, internal whitespace runs are collapsed to a single space,
391	     * and the result is lower-cased (e.g. {@code "  john   smith "} and {@code "John Smith"}
392	     * both normalize to {@code "john smith"}). Returns {@code null} for a {@code null} input.
393	     */
394	    private static String normalize(String value) {
395	        if (value == null) {
396	            return null;
397	        }
398	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
399	    }
400	
401	    @Override
402	    @Transactional(readOnly = true)
403	    public Collection<Owner> findOwnerByLastName(String lastName) throws DataAccessException {
404	        return ownerRepository.findByLastName(lastName);
405	    }
406	
407	    @Override
408	    @Transactional(readOnly = true)
409	    public Collection<Visit> findVisitsByPetId(int petId) {
410	        return visitRepository.findByPetId(petId);
411	    }
412	
413	    @Override
414	    @Transactional(readOnly = true)
415	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
416	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
417	    }
418	
419	    private <T> T findEntityById(Supplier<T> supplier) {
420	        try {
421	            return supplier.get();
422	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
423	            // Just ignore not found exceptions for Jdbc/Jpa realization
424	            return null;
425	        }
426	    }
427	
428	}
